use leptos::prelude::*;
use leptos_meta::Title;

// The Publications block merges the curated narrative cards with one card
// per publication from the ORCID snapshot baked in at build time
// (src/orcid_data.rs, regenerated by scripts/fetch-orcid.py) — each card
// carries the work's DOI link, so the record and its validation link live
// in one place. Only the Software list is refreshed in the browser from
// the ORCID public API by /js/orcid.js.

/// Publications in the ORCID snapshot that must not become cards of their
/// own: the CORR letter and the Kyber Odyssey poster are carried by the
/// curated cards in the Publications block (matched here by DOI), and
/// "First, Do No Harm" is research in progress, not a publication (Matt's
/// ruling, 2026-10-13) — it appears on this page only as a tracker entry.
const CARD_EXCLUDED_DOIS: &[&str] = &["10.1097/corr.0000000000003001", "10.48448/kwd5-1j32"];
const CARD_EXCLUDED_TITLES: &[&str] =
    &["First, Do No Harm: On Making AI Safe, Secure and Trustworthy"];

/// Whether an ORCID-snapshot work becomes a publication card.
fn card_included(work: &crate::orcid_data::Work) -> bool {
    work.kind != "software"
        && !CARD_EXCLUDED_DOIS.contains(&work.doi)
        && !CARD_EXCLUDED_TITLES.contains(&work.title)
}

/// The format a work's record states, if any: its ORCID work type, refined
/// to "Case report" where the title itself says so. A work the record
/// carries as "other" states no format and yields None.
fn format_label(work: &crate::orcid_data::Work) -> Option<String> {
    if work.title.to_lowercase().contains("case report")
        && (work.kind == "journal-article" || work.kind == "other")
    {
        return Some("Case report".to_string());
    }
    match work.kind {
        "data-set" => Some("Dataset".to_string()),
        "journal-article" => Some("Journal article".to_string()),
        "lecture-speech" => Some("Talk".to_string()),
        "preprint" => Some("Preprint".to_string()),
        _ => None,
    }
}

/// One-line provenance for a publication card: format and venue where the
/// record states them, and the year. The snapshot's venue falls back to
/// the work type when a work has no journal or venue, so a venue that
/// merely repeats the type (or "other") states nothing and is dropped.
fn provenance_line(work: &crate::orcid_data::Work) -> String {
    let mut parts: Vec<String> = Vec::new();
    if let Some(label) = format_label(work) {
        parts.push(label);
    }
    if !work.venue.is_empty() && work.venue != work.kind && work.venue != "other" {
        parts.push(work.venue.to_string());
    }
    let head = parts.join(" \u{2014} ");
    if head.is_empty() {
        work.year.to_string()
    } else if work.year.is_empty() {
        head
    } else {
        format!("{head} ({})", work.year)
    }
}

/// Project mark for a tracker entry, keyed by the entry's tags; the
/// mindthegap entry carries no project tag, so it keys off its title.
/// Returns (image slug, alt text) for the entries that have a mark.
fn tracker_mark(tags: &[&str], title: &str) -> Option<(&'static str, &'static str)> {
    for slug in ["bunker", "periscope", "phlow", "tko"] {
        if tags.contains(&slug) {
            return Some((slug, slug));
        }
    }
    if title.starts_with("Mind the Gap") {
        return Some(("mindthegap", "Mind the Gap"));
    }
    None
}

#[component]
pub fn Research() -> impl IntoView {
    view! {
        <Title text="Research - Qompass AI" />
        <section class="page research-page">
            <p class="page-bearing">"ODYSSEY — PUBLICATIONS & PREPRINTS"</p>
            <h1>"Research"</h1>
            <p class="page-lede">
                "Peer-reviewed work, preprints, and benchmark studies. The complete record "
                "below is drawn live from "
                <a href="https://orcid.org/0000-0002-0302-4812">"ORCID 0000-0002-0302-4812"</a>
                " — when the ORCID record changes, this page follows."
            </p>
            <blockquote class="page-motto">
                <p>
                    "Quality is a characteristic of thought and statement that is recognized "
                    "by a nonthinking process. Because definitions are a product of rigid, "
                    "formal thinking, quality cannot be defined."
                </p>
                <cite class="motto-cite">
                    "— Robert M. Pirsig, Zen and the Art of Motorcycle Maintenance"
                </cite>
            </blockquote>
            <h2 class="record-head">"Publications"</h2>
            <p class="record-blurb">
                <a href="https://orcid.org">"ORCID"</a>
                " — the Open Researcher and Contributor ID — is a persistent identifier for "
                "researchers: one ID that ties a scholar's publications, software, and datasets "
                "together across publishers and repositories, so a record can't be confused with "
                "anyone else's. This is Matt Porter's complete record, synced from his "
                <a href="https://orcid.org/0000-0002-0302-4812">"ORCID profile"</a>
                "; every entry links to the work itself."
            </p>
            <div class="entry-list">
                <article class="entry">
                    <p class="entry-kind">"BENCHMARK STUDY"</p>
                    <img class="entry-mark" src="/img/projects/odyssey.webp" alt="Odyssey" />
                    <h2>"Post-quantum KEM benchmarking (qompassai/KO)"</h2>
                    <p>
                        "24 NIST post-quantum key-encapsulation mechanisms benchmarked head to "
                        "head — timings, memory, and failure behavior, measured rather than "
                        "quoted from spec sheets. Submitted to the 2025 AMA Research Challenge."
                    </p>
                    <p>
                        "Presented as the poster 'Kyber Odyssey: Charting a course for secure "
                        "innovation in a post-Crowdstrike world' at the AMA Research Challenge 2024."
                    </p>
                    <p>
                        "Poster DOI: "
                        <a href="https://doi.org/10.48448/kwd5-1j32">"10.48448/kwd5-1j32"</a>
                    </p>
                </article>
                <article class="entry">
                    <p class="entry-kind">
                        "PEER-REVIEWED LETTER — CLINICAL ORTHOPAEDICS AND RELATED RESEARCH (2024)"
                    </p>
                    <h2>"Generative AI and value-based healthcare"</h2>
                    <p>
                        "On what generative AI actually changes in value-based care — where it "
                        "earns its cost, where it does not, and the evidence bar it should be "
                        "held to before it touches a patient."
                    </p>
                    <p>
                        "DOI: "
                        <a href="https://doi.org/10.1097/corr.0000000000003001">
                            "10.1097/corr.0000000000003001"
                        </a>
                    </p>
                </article>
                <article class="entry">
                    <p class="entry-kind">"PEER REVIEW"</p>
                    <h2>"Reviewer — JGME, JMIR, and orthopaedic journals"</h2>
                    <p>
                        "Ongoing peer review of manuscripts on LLMs in medical education and "
                        "clinical AI — the same evidence standard, applied to other people's "
                        "claims."
                    </p>
                </article>
                {crate::orcid_data::WORKS
                    .iter()
                    .filter(|w| card_included(w))
                    .map(|w| {
                        view! {
                            <article class="entry">
                                <p class="entry-kind">{provenance_line(w)}</p>
                                <h2>{w.title}</h2>
                                {(!w.doi.is_empty())
                                    .then(|| {
                                        let doi_url = format!("https://doi.org/{}", w.doi);
                                        view! {
                                            <p>
                                                "DOI: "
                                                <a href={doi_url}>{w.doi}</a>
                                            </p>
                                        }
                                    })}
                                {(w.doi.is_empty())
                                    .then(|| {
                                        view! {
                                            <p>
                                                "Record: "
                                                <a href={w.url}>{w.url}</a>
                                            </p>
                                        }
                                    })}
                            </article>
                        }
                    })
                    .collect_view()}
            </div>
            <h2 class="record-head">"On the Odyssey — Research in Progress"</h2>
            <p class="record-meta">
                "The working log, published as it goes. Only entries flagged public appear "
                "here; abstracts appear only when flagged ready for daylight."
            </p>
            <div class="entry-list">
                {crate::tracker_data::TRACKER
                    .iter()
                    .map(|t| {
                        let mark = tracker_mark(t.tags, t.title);
                        let stage_label = match t.stage {
                            "soundings" => "STAGE — SOUNDINGS",
                            "drafting" => "STAGE — DRAFTING",
                            "in-review" => "STAGE — IN REVIEW",
                            "ready" => "STAGE — READY TO PUBLISH",
                            "published" => "STAGE — PUBLISHED",
                            _ => "STAGE — ANCHORED",
                        };
                        view! {
                            <article class="entry tracker-entry">
                                <p class="entry-kind">
                                    {stage_label} " · UPDATED " {t.updated}
                                </p>
                                {mark.map(|(slug, name)| {
                                    view! {
                                        <img
                                            class="tracker-mark"
                                            src={format!("/img/projects/{slug}.webp")}
                                            alt={name}
                                        />
                                    }
                                })}
                                <h2>{t.title}</h2>
                                <p>{t.topic}</p>
                                {(!t.abstract_text.is_empty())
                                    .then(|| {
                                        view! {
                                            <p class="tracker-abstract">{t.abstract_text}</p>
                                        }
                                    })}
                                {(!t.next_step.is_empty())
                                    .then(|| {
                                        view! {
                                            <p class="tracker-next">
                                                <span class="tracker-next-label">"Next: "</span>
                                                {t.next_step}
                                            </p>
                                        }
                                    })}
                            </article>
                        }
                    })
                    .collect_view()}
            </div>
            <h2 class="record-head">"Software"</h2>
            <p class="record-meta">
                <span id="orcid-status">"Snapshot from build time; refreshing from ORCID…"</span>
            </p>
            <p class="record-meta">"Self-published by Qompass AI · archived on Zenodo"</p>
            <ul class="record-list" id="orcid-software">
                {crate::orcid_data::WORKS
                    .iter()
                    .filter(|w| w.kind == "software")
                    .map(|w| {
                        view! {
                            <li class="record-item">
                                <span class="record-year">{w.year}</span>
                                <span class="record-title">
                                    <a href={w.url}>{w.title}</a>
                                </span>
                                {(!w.doi.is_empty())
                                    .then(|| {
                                        let doi_url = format!("https://doi.org/{}", w.doi);
                                        view! {
                                            <span class="record-doi">
                                                "DOI: "
                                                <a href={doi_url}>{w.doi}</a>
                                            </span>
                                        }
                                    })}
                            </li>
                        }
                    })
                    .collect_view()}
            </ul>
        </section>
        <script type="module" src="/js/orcid.js"></script>
    }
}
